    "indicator": "US Core CPI (April 2026 Forecast)",
    "reading": "0.41% MoM SA",
    "interpretation": "Reflects firm underlying price pressures, particularly in services."
   },
   {
    "indicator": "Energy CPI (April 2026 Forecast)",
    "reading": "17.3% YoY",
    "interpretation": "Significant upward pressure on headline inflation due to motor fuel price increases."
   }
  ],
  "risks": [
   "Energy crisis impact on services (currently limited to airfares).",
   "Conflicting narratives like lower immigration (inflationary) vs. AI (deflationary) which are not yet dominating the 1Y outlook.",
   "Base effects from gasoline futures backwardation."
  ],
  "charts": [
   "Charts detail the MoM and YoY trends for headline, core, food, energy, and services components, highlighting the impact of energy volatility and BLS methodology changes on shelter/OER."
  ],
